draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // tree trunk
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 50);
  ctx.lineTo(W / 2, H);
  ctx.stroke();

  // tree growth
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 50, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // years
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W / 2, H / 2 + 50, 20 + 10 * Math.sin(t) + i * 5, 2 * Math.PI * i / 10, 2 * Math.PI * (i + 1) / 10);
    ctx.stroke();
  }

  ctx.restore();
}
